package justepicdimensions.monitor;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import justepicdimensions.dimension.JEDDimensionFiles;
import net.minecraft.resources.ResourceLocation;

/** Worker-only append, compaction and range queries. No native world objects cross this boundary. */
public final class JEDMonitoringHistory {
 private final Path root;
 private final Map<ResourceLocation,Bucket> minutes=new HashMap<>();
 private final Map<ResourceLocation,Long> cleaned=new HashMap<>();
 private final Map<ResourceLocation,JEDMonitoringPolicy> saved=new HashMap<>();
 public JEDMonitoringHistory(Path world){root=world.toAbsolutePath().normalize().resolve("data/justepicdimensions/monitoring");}
 public Path directory(ResourceLocation id){Path p=root.resolve(id.getNamespace()).resolve(id.getPath()).normalize();JEDDimensionFiles.requireSafe(root,p,false);return p;}
 private Path file(ResourceLocation id,String kind,long time){var p=directory(id).resolve(kind+"-"+Instant.ofEpochMilli(time).atZone(ZoneOffset.UTC).toLocalDate()+".jsonl");JEDDimensionFiles.requireSafe(root,p,false);return p;}
 private void append(ResourceLocation id,String kind,JsonObject row)throws IOException{var p=file(id,kind,row.get("time").getAsLong());Files.createDirectories(p.getParent());Files.writeString(p,row+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND,LinkOption.NOFOLLOW_LINKS);}
 public void add(ResourceLocation id,JEDMonitoringPolicy policy,JsonObject row)throws IOException{if(policy.mode().equals("session"))return;configure(id,policy,true);append(id,"detail",row);{long minute=row.get("time").getAsLong()/60000;var previous=minutes.get(id);if(previous!=null&&previous.minute!=minute){append(id,"summary",previous.json());minutes.remove(id);}minutes.computeIfAbsent(id,k->new Bucket(minute)).add(row);}long now=row.get("time").getAsLong();if(now-cleaned.getOrDefault(id,0L)>=60000){clean(id,policy,now);cleaned.put(id,now);}}
 public void configure(ResourceLocation id,JEDMonitoringPolicy policy,boolean create)throws IOException{if(!create&&!Files.isDirectory(directory(id)))return;if(!policy.equals(saved.get(id))){var meta=new JsonObject();meta.addProperty("id",id.toString());meta.addProperty("format_version",1);meta.addProperty("mode",policy.mode());meta.addProperty("detail_seconds",policy.detailSeconds());meta.addProperty("retention_seconds",policy.retentionSeconds());var dir=directory(id);Files.createDirectories(dir);JEDDimensionFiles.writeDurable(dir.resolve("policy.json"),meta);saved.put(id,policy);}}
 public void maintenance(long now)throws IOException{if(!Files.isDirectory(root))return;try(var paths=Files.walk(root)){for(var p:paths.filter(p->p.getFileName().toString().equals("policy.json")).toList()){JEDDimensionFiles.requireSafe(root,p,false);var m=JsonParser.parseString(Files.readString(p)).getAsJsonObject();var id=justepicdimensions.definition.JEDDimensionDefinition.id(m.get("id").getAsString(),"history metadata");if(!p.getParent().equals(directory(id)))throw new IOException("Monitoring metadata path mismatch");var policy=new JEDMonitoringPolicy(5,m.get("mode").getAsString(),m.get("detail_seconds").getAsInt(),m.get("retention_seconds").getAsInt(),3600,List.of());if(policy.retentionSeconds()<1||policy.detailSeconds()<1)throw new IOException("Invalid monitoring retention metadata");clean(id,policy,now);}}}
 public void finish()throws IOException{for(var e:minutes.entrySet())append(e.getKey(),"summary",e.getValue().json());minutes.clear();}
 public void clean(ResourceLocation id,JEDMonitoringPolicy policy,long now)throws IOException{var dir=directory(id);if(!Files.isDirectory(dir))return;try(var paths=Files.list(dir)){for(var p:paths.toList()){String n=p.getFileName().toString();if(!n.matches("(detail|summary)-\\d{4}-\\d{2}-\\d{2}\\.jsonl"))continue;JEDDimensionFiles.requireSafe(root,p,false);long cutoff=now-1000L*(n.startsWith("detail")&&policy.mode().equals("summarized")?Math.min(policy.detailSeconds(),policy.retentionSeconds()):policy.retentionSeconds());long day=LocalDate.parse(n.substring(n.indexOf('-')+1,n.length()-6)).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();if(day+86400000L<=cutoff){Files.deleteIfExists(p);continue;}if(day<cutoff)trim(p,cutoff);}}}
 private void trim(Path p,long cutoff)throws IOException{var keep=new ArrayList<String>();boolean changed=false;try(var in=Files.newBufferedReader(p,StandardCharsets.UTF_8)){String line;while((line=in.readLine())!=null){long time;try{time=JsonParser.parseString(line).getAsJsonObject().get("time").getAsLong();}catch(RuntimeException error){throw new IOException("Malformed monitoring history retained: "+p,error);}if(time>=cutoff)keep.add(line);else changed=true;}}if(!changed)return;if(keep.isEmpty()){Files.deleteIfExists(p);return;}Path temp=Files.createTempFile(p.getParent(),".monitor-trim-",".tmp");try{Files.write(temp,keep,StandardCharsets.UTF_8);try{Files.move(temp,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,p,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(temp);}}
 public JsonObject query(ResourceLocation id,JEDMonitoringPolicy policy,long since,long now,String metric)throws IOException{
  if(!JEDMonitoringPolicy.METRICS.contains(metric))throw new IllegalArgumentException("Unknown monitoring metric");var result=new JsonObject();var values=new TreeMap<Long,Point>();var detailedMinutes=new HashSet<Long>();long start=Math.max(since,now-1000L*policy.retentionSeconds()),width=Math.max(1,(now-start+999)/1000);int errors=0;var dir=directory(id);
  if(Files.isDirectory(dir))try(var paths=Files.list(dir)){for(var p:paths.sorted().toList()){String name=p.getFileName().toString();if(!name.matches("(detail|summary)-\\d{4}-\\d{2}-\\d{2}\\.jsonl"))continue;JEDDimensionFiles.requireSafe(root,p,false);long day=LocalDate.parse(name.substring(name.indexOf('-')+1,name.length()-6)).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();if(day+86400000L<start||day>now)continue;boolean summary=name.startsWith("summary");try(var in=Files.newBufferedReader(p,StandardCharsets.UTF_8)){String line;while((line=in.readLine())!=null)try{var row=JsonParser.parseString(line).getAsJsonObject();long time=row.get("time").getAsLong();if(time<start||time>now||summary&&detailedMinutes.contains(time/60000))continue;if(!summary&&row.has(metric))detailedMinutes.add(time/60000);if(row.has(metric)&&row.get("loaded").getAsBoolean()||row.has(metric)&&metric.startsWith("disk_")){var point=values.computeIfAbsent((time-start)/width,k->new Point());point.add(time,row.get(metric).getAsDouble(),row.has(metric+"_samples")?Math.max(1,row.get(metric+"_samples").getAsLong()):1);if(row.has(metric+"_min"))point.min=Math.min(point.min,row.get(metric+"_min").getAsDouble());if(row.has(metric+"_max"))point.max=Math.max(point.max,row.get(metric+"_max").getAsDouble());}}catch(RuntimeException malformed){errors++;}}}}
  var out=new JsonArray();for(var p:values.values())out.add(p.json());result.add("points",out);result.addProperty("history_errors",errors);return result;
 }
 public static final class Point{long time,count;double sum,min=Double.POSITIVE_INFINITY,max=Double.NEGATIVE_INFINITY;public void add(long t,double n){add(t,n,1);}public void add(long t,double n,long weight){time=Math.max(time,t);count+=weight;sum+=n*weight;min=Math.min(min,n);max=Math.max(max,n);}public JsonObject json(){var j=new JsonObject();j.addProperty("time",time);j.addProperty("value",sum/count);j.addProperty("min",min);j.addProperty("max",max);j.addProperty("samples",count);return j;}}
 private static final class Bucket{final long minute;final Map<String,Point> values=new HashMap<>();boolean loaded;Bucket(long minute){this.minute=minute;}void add(JsonObject row){loaded|=row.get("loaded").getAsBoolean();for(String metric:JEDMonitoringPolicy.METRICS)if(row.has(metric))values.computeIfAbsent(metric,k->new Point()).add(row.get("time").getAsLong(),row.get(metric).getAsDouble());}JsonObject json(){var j=new JsonObject();j.addProperty("time",minute*60000);j.addProperty("loaded",loaded);values.forEach((k,p)->{j.addProperty(k,k.endsWith("_max")||k.endsWith("_p95")?p.max:p.sum/p.count);j.addProperty(k+"_samples",p.count);j.addProperty(k+"_min",p.min);j.addProperty(k+"_max",p.max);});return j;}}
}
